# =============================================================================
# OneMind OS — Dell Inspiron 24-7459 (omos-dell-edge) Windows 10 Optimizer
# Generated by Legacy (Mother) — 2026-07-14
# Run as Administrator: Right-click PowerShell → Run as Administrator
# =============================================================================

Write-Host "=== OneMind OS — omos-dell-edge Performance Optimizer ===" -ForegroundColor Cyan
Write-Host "Running as: $($env:USERNAME) on $($env:COMPUTERNAME)" -ForegroundColor Gray
Write-Host ""

# ── PHASE 1: Power Plan — High Performance ───────────────────────────────────
Write-Host "[1/10] Setting Power Plan to High Performance..." -ForegroundColor Yellow
powercfg -setactive 8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c
# If GUID not found, create it:
$currentPlan = powercfg -getactivescheme
if ($currentPlan -notmatch "High performance") {
    powercfg -duplicatescheme 8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c 2>$null
    powercfg -setactive 8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c 2>$null
}
# Disable sleep/hibernate (always-on C2 node)
powercfg -change -standby-timeout-ac 0
powercfg -change -hibernate-timeout-ac 0
powercfg -change -monitor-timeout-ac 0
powercfg -h off
Write-Host "  ✓ High Performance power plan active, sleep/hibernate disabled" -ForegroundColor Green

# ── PHASE 2: Disable Visual Effects — Pure Performance ───────────────────────
Write-Host "[2/10] Disabling Windows visual effects..." -ForegroundColor Yellow
$regPath = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects"
New-Item -Path $regPath -Force | Out-Null
Set-ItemProperty -Path $regPath -Name "VisualFXSetting" -Value 2
# Set SystemPropertiesPerformance registry keys
$perfPath = "HKCU:\Control Panel\Desktop"
Set-ItemProperty -Path $perfPath -Name "UserPreferencesMask" -Value ([byte[]](0x90,0x12,0x01,0x80,0x10,0x00,0x00,0x00))
Set-ItemProperty -Path "HKCU:\Control Panel\Desktop\WindowMetrics" -Name "MinAnimate" -Value "0" -ErrorAction SilentlyContinue
Write-Host "  ✓ Visual effects minimized" -ForegroundColor Green

# ── PHASE 3: Disable Startup Programs (bloatware) ────────────────────────────
Write-Host "[3/10] Disabling non-essential startup programs..." -ForegroundColor Yellow
$startupItems = @(
    "OneDrive", "Teams", "Skype", "Discord", "Spotify",
    "AdobeUpdater", "AcroTray", "iTunesHelper",
    "Dell Customer Connect", "Dell Digital Delivery",
    "Dell Foundation Services", "Dell Help & Support",
    "SupportAssist", "Dell SupportAssist Remediation",
    "Dell Optimizer Service", "Dell Peripheral Manager"
)
foreach ($item in $startupItems) {
    $regKeys = @(
        "HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run",
        "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run",
        "HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Run"
    )
    foreach ($key in $regKeys) {
        if (Get-ItemProperty -Path $key -Name $item -ErrorAction SilentlyContinue) {
            Remove-ItemProperty -Path $key -Name $item -ErrorAction SilentlyContinue
            Write-Host "  ✓ Disabled: $item" -ForegroundColor Green
        }
    }
}

# ── PHASE 4: Disable Unnecessary Windows Services ────────────────────────────
Write-Host "[4/10] Disabling unnecessary Windows services..." -ForegroundColor Yellow
$disableServices = @(
    "WSearch",          # Windows Search indexing — eats CPU/disk
    "SysMain",          # Superfetch — counterproductive on SSD/limited RAM
    "DiagTrack",        # Connected User Experiences (telemetry)
    "dmwappushservice", # WAP Push Message Routing (telemetry)
    "MapsBroker",       # Downloaded Maps Manager
    "XblAuthManager",   # Xbox Live Auth
    "XblGameSave",      # Xbox Live Game Save
    "XboxNetApiSvc",    # Xbox Live Networking
    "wuauserv"          # Windows Update — DISABLE on C2 node (update manually)
)
foreach ($svc in $disableServices) {
    try {
        Stop-Service -Name $svc -Force -ErrorAction SilentlyContinue
        Set-Service -Name $svc -StartupType Disabled -ErrorAction SilentlyContinue
        Write-Host "  ✓ Disabled service: $svc" -ForegroundColor Green
    } catch {
        Write-Host "  - Skipped (not found): $svc" -ForegroundColor Gray
    }
}

# ── PHASE 5: NVIDIA 940M — Force Performance Mode ────────────────────────────
Write-Host "[5/10] Configuring NVIDIA 940M for performance..." -ForegroundColor Yellow
# Set NVIDIA power management to prefer max performance
$nvidiaPaths = @(
    "HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e968-e325-11ce-bfc1-08002be10318}\0000",
    "HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e968-e325-11ce-bfc1-08002be10318}\0001"
)
foreach ($path in $nvidiaPaths) {
    if (Test-Path $path) {
        Set-ItemProperty -Path $path -Name "PerfLevelSrc" -Value 0x2222 -ErrorAction SilentlyContinue
        Set-ItemProperty -Path $path -Name "PowerMizerEnable" -Value 0 -ErrorAction SilentlyContinue
        Set-ItemProperty -Path $path -Name "PowerMizerLevel" -Value 1 -ErrorAction SilentlyContinue
        Set-ItemProperty -Path $path -Name "PowerMizerLevelAC" -Value 1 -ErrorAction SilentlyContinue
        Write-Host "  ✓ NVIDIA performance mode set at $path" -ForegroundColor Green
    }
}
# Hardware-accelerated GPU scheduling (HAGS) — helps 940M
$graphicsPath = "HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers"
Set-ItemProperty -Path $graphicsPath -Name "HwSchMode" -Value 2 -ErrorAction SilentlyContinue
Write-Host "  ✓ GPU hardware scheduling enabled" -ForegroundColor Green

# ── PHASE 6: Network — Optimize for TAK / NATS / Tailscale ──────────────────
Write-Host "[6/10] Optimizing network settings for TAK/NATS..." -ForegroundColor Yellow
# Disable Nagle's algorithm (reduces TCP latency — critical for TAK CoT)
$tcpPath = "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces"
Get-ChildItem -Path $tcpPath | ForEach-Object {
    Set-ItemProperty -Path $_.PSPath -Name "TcpAckFrequency" -Value 1 -ErrorAction SilentlyContinue
    Set-ItemProperty -Path $_.PSPath -Name "TCPNoDelay" -Value 1 -ErrorAction SilentlyContinue
}
# DNS — use Cloudflare for speed
Set-DnsClientServerAddress -InterfaceAlias "Ethernet" -ServerAddresses ("1.1.1.1","1.0.0.1") -ErrorAction SilentlyContinue
Set-DnsClientServerAddress -InterfaceAlias "Wi-Fi" -ServerAddresses ("1.1.1.1","1.0.0.1") -ErrorAction SilentlyContinue
# Firewall — allow TAK ports
Write-Host "  Opening TAK firewall ports..." -ForegroundColor Gray
netsh advfirewall firewall add rule name="TAK CoT TLS" dir=out action=allow protocol=TCP remoteport=8089 2>$null
netsh advfirewall firewall add rule name="TAK WebTAK" dir=out action=allow protocol=TCP remoteport=8446 2>$null
netsh advfirewall firewall add rule name="NATS Client" dir=out action=allow protocol=TCP remoteport=4222 2>$null
netsh advfirewall firewall add rule name="NATS WebSocket" dir=out action=allow protocol=TCP remoteport=8080 2>$null
netsh advfirewall firewall add rule name="Tailscale" dir=out action=allow protocol=UDP remoteport=41641 2>$null
Write-Host "  ✓ Network optimized, TAK/NATS/Tailscale ports open" -ForegroundColor Green

# ── PHASE 7: Disk — Optimize for Performance ─────────────────────────────────
Write-Host "[7/10] Optimizing disk settings..." -ForegroundColor Yellow
# Disable last access timestamp (reduces disk I/O)
fsutil behavior set disablelastaccess 1 2>$null
# Disable 8.3 filename creation
fsutil behavior set disable8dot3 1 2>$null
# Set recycle bin to delete directly (C2 node — no need for recycle)
$shell = New-Object -ComObject Shell.Application
Write-Host "  ✓ Disk optimizations applied" -ForegroundColor Green

# ── PHASE 8: RAM — Optimize for WinTAK / Always-On ──────────────────────────
Write-Host "[8/10] Optimizing memory settings..." -ForegroundColor Yellow
# Disable paging executive to RAM (keep kernel in RAM)
Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management" `
    -Name "DisablePagingExecutive" -Value 1 -ErrorAction SilentlyContinue
# Large System Cache — favor system processes (WinTAK)
Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management" `
    -Name "LargeSystemCache" -Value 0 -ErrorAction SilentlyContinue
Write-Host "  ✓ Memory optimized for C2 workload" -ForegroundColor Green

# ── PHASE 9: Windows Update — Disable Auto-Restart ───────────────────────────
Write-Host "[9/10] Blocking Windows Update auto-restart (C2 must not reboot)..." -ForegroundColor Yellow
$wuPath = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate\AU"
New-Item -Path $wuPath -Force | Out-Null
Set-ItemProperty -Path $wuPath -Name "NoAutoRebootWithLoggedOnUsers" -Value 1
Set-ItemProperty -Path $wuPath -Name "AUOptions" -Value 2  # Notify only — never auto-install
Set-ItemProperty -Path $wuPath -Name "ScheduledInstallDay" -Value 0
Write-Host "  ✓ Windows Update: notify-only, no auto-restart" -ForegroundColor Green

# ── PHASE 10: Tailscale + WinTAK Auto-Start ──────────────────────────────────
Write-Host "[10/10] Configuring Tailscale + WinTAK auto-start on boot..." -ForegroundColor Yellow
# Tailscale auto-start (if installed)
$tailscalePath = "$env:LOCALAPPDATA\Programs\Tailscale\tailscale-ipn.exe"
if (Test-Path $tailscalePath) {
    $regRunPath = "HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run"
    Set-ItemProperty -Path $regRunPath -Name "Tailscale" -Value "`"$tailscalePath`""
    Write-Host "  ✓ Tailscale auto-start registered" -ForegroundColor Green
} else {
    Write-Host "  ! Tailscale not found at expected path — install first, then re-run" -ForegroundColor Yellow
}

# WinTAK auto-start (register if installed)
$winTAKPaths = @(
    "C:\Program Files\WinTAK\WinTAK.exe",
    "C:\Program Files (x86)\WinTAK\WinTAK.exe",
    "$env:LOCALAPPDATA\Programs\WinTAK\WinTAK.exe"
)
foreach ($path in $winTAKPaths) {
    if (Test-Path $path) {
        $regRunPath = "HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run"
        Set-ItemProperty -Path $regRunPath -Name "WinTAK" -Value "`"$path`""
        Write-Host "  ✓ WinTAK auto-start registered at: $path" -ForegroundColor Green
        break
    }
}

# ── SUMMARY ──────────────────────────────────────────────────────────────────
Write-Host ""
Write-Host "=== Optimization Complete ===" -ForegroundColor Cyan
Write-Host "Applied:" -ForegroundColor White
Write-Host "  ✓ High Performance power plan (sleep/hibernate disabled)" -ForegroundColor Green
Write-Host "  ✓ Visual effects minimized" -ForegroundColor Green
Write-Host "  ✓ Startup bloat disabled" -ForegroundColor Green
Write-Host "  ✓ Unnecessary services disabled (telemetry, Xbox, Search, Superfetch)" -ForegroundColor Green
Write-Host "  ✓ NVIDIA 940M: max performance mode" -ForegroundColor Green
Write-Host "  ✓ Network: low-latency TCP, TAK/NATS/Tailscale firewall rules" -ForegroundColor Green
Write-Host "  ✓ Disk: last-access disabled, 8.3 names disabled" -ForegroundColor Green
Write-Host "  ✓ Memory: kernel in RAM, optimized for C2" -ForegroundColor Green
Write-Host "  ✓ Windows Update: notify-only, no auto-restart" -ForegroundColor Green
Write-Host "  ✓ Tailscale + WinTAK auto-start on boot" -ForegroundColor Green
Write-Host ""
Write-Host "ACTION REQUIRED: Restart Windows to apply all changes." -ForegroundColor Red
Write-Host "After restart, verify Tailscale connects and WinTAK auto-launches." -ForegroundColor Yellow
Write-Host ""
Write-Host "TAK Server: 152.42.155.95:8089 (CoT TLS) | 152.42.155.95:8446 (WebTAK)" -ForegroundColor Cyan
Write-Host "Tailscale IP (this machine): check with: tailscale ip -4" -ForegroundColor Cyan
